package com.yungnickyoung.minecraft.bettercaves.config;

import net.minecraftforge.common.config.ConfigManager;
import net.minecraftforge.common.config.ConfigEntry;
import net.minecraftforge.common.config.Config;
import net.minecraftforge.common.config.Config.Comment;
import net.minecraftforge.common.config.Config.Name;
import net.minecraftforge.common.config.Config.RequiresWorldRestart;

@Config(
   modid = "bettercaves",
   name = "bettercaves-1_12_2"
)
public class Configuration {
   @Name("Underground Generation")
   @Comment({"Configure settings related to caves, caverns, ravines and more."})
   public static ConfigUndergroundGen caveSettings = new ConfigUndergroundGen();
   @Name("Bedrock Generation")
   @Comment({"Configure how bedrock generates in the overworld and nether."})
   public static ConfigBedrockGen bedrockSettings = new ConfigBedrockGen();
   @Name("Debug settings")
   @Comment({"Don't mess with these settings for normal gameplay."})
   public static ConfigDebug debugsettings = new ConfigDebug();
   @Name("Whitelisted Dimension IDs")
   @Comment({"List of ID's of dimensions that will have Better Caves. Ignored if Global Whitelisting is enabled."})
   @RequiresWorldRestart
   public static int[] whitelistedDimensionIDs = new int[]{0};
   @Name("Enable Global Whitelist")
   @Comment({"Automatically enables Better Caves in every possible dimension, except for the End.\n    If this is enabled, the Whitelisted Dimension IDs option is ignored.\nDefault: false"})
   @RequiresWorldRestart
   public static boolean enableGlobalWhitelist = false;

   public Configuration() {
   }

   public static void register() {
      ConfigManager.register("bettercaves", "bettercaves-1_12_2", "general", null,
         ConfigEntry.category("Underground Generation",
            ConfigEntry.category("Caves",
               ConfigEntry.category("Type 1 Caves",
                  ConfigEntry.value("Type 1 Cave Minimum Altitude", int.class, () -> Configuration.caveSettings.caves.cubicCave.caveBottom, v -> Configuration.caveSettings.caves.cubicCave.caveBottom = (Integer)v).comment("The minimum y-coordinate at which type 1 caves can generate.\nDefault: 1").langKey("bettercaves.general.underground generation.caves.type 1 caves.cavebottom").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Type 1 Cave Maximum Altitude", int.class, () -> Configuration.caveSettings.caves.cubicCave.caveTop, v -> Configuration.caveSettings.caves.cubicCave.caveTop = (Integer)v).comment("The maximum y-coordinate at which type 1 caves can generate.\nDefault: 80").langKey("bettercaves.general.underground generation.caves.type 1 caves.cavetop").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Type 1 Cave Surface Cutoff Depth", int.class, () -> Configuration.caveSettings.caves.cubicCave.caveSurfaceCutoff, v -> Configuration.caveSettings.caves.cubicCave.caveSurfaceCutoff = (Integer)v).comment("The depth from a given point on the surface at which type 1 caves start to close off.\n    Will use the Max Cave Altitude instead of surface height if it is lower.\n    Will use the Max Cave Altitude no matter what if Override Surface Detection is enabled.\nDefault: 15 (recommended)").langKey("bettercaves.general.underground generation.caves.type 1 caves.cavesurfacecutoff").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Compression - Vertical", float.class, () -> Configuration.caveSettings.caves.cubicCave.yCompression, v -> Configuration.caveSettings.caves.cubicCave.yCompression = (Float)v).comment("Stretches caves vertically. Lower value = taller caves with steeper drops.\nDefault: 5.0 (recommended)").langKey("bettercaves.general.underground generation.caves.type 1 caves.ycompression").range(0.0, 100.0).requiresWorldRestart(),
                  ConfigEntry.value("Compression - Horizontal", float.class, () -> Configuration.caveSettings.caves.cubicCave.xzCompression, v -> Configuration.caveSettings.caves.cubicCave.xzCompression = (Float)v).comment("Stretches caves horizontally. Lower value = wider caves.\nDefault: 1.6 (recommended)").langKey("bettercaves.general.underground generation.caves.type 1 caves.xzcompression").range(0.0, 100.0).requiresWorldRestart(),
                  ConfigEntry.value("Type 1 Cave Priority", int.class, () -> Configuration.caveSettings.caves.cubicCave.cavePriority, v -> Configuration.caveSettings.caves.cubicCave.cavePriority = (Integer)v).comment("Determines how frequently Type 1 Caves spawn. 0 = will not spawn at all.\nDefault: 10").langKey("bettercaves.general.underground generation.caves.type 1 caves.cavepriority").range(0, 10).requiresWorldRestart()).comment("Settings used in the generation of type 1 caves, which are more worm-like.").langKey("bettercaves.general.underground generation.caves.cubiccave"),
               ConfigEntry.category("Type 2 Caves",
                  ConfigEntry.value("Type 2 Cave Minimum Altitude", int.class, () -> Configuration.caveSettings.caves.simplexCave.caveBottom, v -> Configuration.caveSettings.caves.simplexCave.caveBottom = (Integer)v).comment("The minimum y-coordinate at which type 2 caves can generate.\nDefault: 1").langKey("bettercaves.general.underground generation.caves.type 2 caves.cavebottom").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Type 2 Cave Maximum Altitude", int.class, () -> Configuration.caveSettings.caves.simplexCave.caveTop, v -> Configuration.caveSettings.caves.simplexCave.caveTop = (Integer)v).comment("The maximum y-coordinate at which type 2 caves can generate.\nDefault: 80").langKey("bettercaves.general.underground generation.caves.type 2 caves.cavetop").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Type 2 Cave Surface Cutoff Depth", int.class, () -> Configuration.caveSettings.caves.simplexCave.caveSurfaceCutoff, v -> Configuration.caveSettings.caves.simplexCave.caveSurfaceCutoff = (Integer)v).comment("The depth from a given point on the surface at which type 2 caves start to close off.\n    Will use the Max Cave Altitude instead of surface height if it is lower.\n    Will use the Max Cave Altitude no matter what if Override Surface Detection is enabled.\nDefault: 15 (recommended)").langKey("bettercaves.general.underground generation.caves.type 2 caves.cavesurfacecutoff").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Compression - Vertical", float.class, () -> Configuration.caveSettings.caves.simplexCave.yCompression, v -> Configuration.caveSettings.caves.simplexCave.yCompression = (Float)v).comment("Stretches caves vertically. Lower value = taller caves with steeper drops.\nDefault: 2.2 (recommended)").langKey("bettercaves.general.underground generation.caves.type 2 caves.ycompression").range(0.0, 100.0).requiresWorldRestart(),
                  ConfigEntry.value("Compression - Horizontal", float.class, () -> Configuration.caveSettings.caves.simplexCave.xzCompression, v -> Configuration.caveSettings.caves.simplexCave.xzCompression = (Float)v).comment("Stretches caves horizontally. Lower value = wider caves.\nDefault: 0.9 (recommended)").langKey("bettercaves.general.underground generation.caves.type 2 caves.xzcompression").range(0.0, 100.0).requiresWorldRestart(),
                  ConfigEntry.value("Type 2 Cave Priority", int.class, () -> Configuration.caveSettings.caves.simplexCave.cavePriority, v -> Configuration.caveSettings.caves.simplexCave.cavePriority = (Integer)v).comment("Determines how frequently Type 2 Caves spawn. 0 = will not spawn at all.\nDefault: 5").langKey("bettercaves.general.underground generation.caves.type 2 caves.cavepriority").range(0, 10).requiresWorldRestart()).comment("Settings used in the generation of type 2 caves, which tend to be more open and spacious.").langKey("bettercaves.general.underground generation.caves.simplexcave"),
               ConfigEntry.category("Surface Caves",
                  ConfigEntry.value("Enable Surface Caves", boolean.class, () -> Configuration.caveSettings.caves.surfaceCave.enableSurfaceCaves, v -> Configuration.caveSettings.caves.surfaceCave.enableSurfaceCaves = (Boolean)v).comment("Set to true to enable vanilla-like caves which provide nice, natural-looking openings at the surface.\nDefault: true").langKey("bettercaves.general.underground generation.caves.surface caves.enablesurfacecaves"),
                  ConfigEntry.value("Surface Cave Minimum Altitude", int.class, () -> Configuration.caveSettings.caves.surfaceCave.caveBottom, v -> Configuration.caveSettings.caves.surfaceCave.caveBottom = (Integer)v).comment("The minimum y-coordinate at which surface caves can generate.\nDefault: 40").langKey("bettercaves.general.underground generation.caves.surface caves.cavebottom").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Surface Cave Maximum Altitude", int.class, () -> Configuration.caveSettings.caves.surfaceCave.caveTop, v -> Configuration.caveSettings.caves.surfaceCave.caveTop = (Integer)v).comment("The maximum y-coordinate at which surface caves can generate.\nDefault: 128").langKey("bettercaves.general.underground generation.caves.surface caves.cavetop").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Surface Cave Density", int.class, () -> Configuration.caveSettings.caves.surfaceCave.caveDensity, v -> Configuration.caveSettings.caves.surfaceCave.caveDensity = (Integer)v).comment("The density of surface caves. Higher = more caves, closer together. \nDefault: 17").langKey("bettercaves.general.underground generation.caves.surface caves.cavedensity").range(0, 100).requiresWorldRestart()).comment("Settings used in the generation of vanilla-like caves near the surface.").langKey("bettercaves.general.underground generation.caves.surfacecave"),
               ConfigEntry.category("Vanilla Caves",
                  ConfigEntry.value("Vanilla Cave Minimum Altitude", int.class, () -> Configuration.caveSettings.caves.vanillaCave.caveBottom, v -> Configuration.caveSettings.caves.vanillaCave.caveBottom = (Integer)v).comment("The minimum y-coordinate at which vanilla caves can generate.\nDefault: 8").langKey("bettercaves.general.underground generation.caves.vanilla caves.cavebottom").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Vanilla Cave Maximum Altitude", int.class, () -> Configuration.caveSettings.caves.vanillaCave.caveTop, v -> Configuration.caveSettings.caves.vanillaCave.caveTop = (Integer)v).comment("The maximum y-coordinate at which vanilla caves can generate.\nDefault: 128").langKey("bettercaves.general.underground generation.caves.vanilla caves.cavetop").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Vanilla Cave Density", int.class, () -> Configuration.caveSettings.caves.vanillaCave.caveDensity, v -> Configuration.caveSettings.caves.vanillaCave.caveDensity = (Integer)v).comment("The density of vanilla caves. Higher = more caves, closer together. \nDefault: 14 (value used in vanilla)").langKey("bettercaves.general.underground generation.caves.vanilla caves.cavedensity").range(0, 100).requiresWorldRestart(),
                  ConfigEntry.value("Vanilla Cave Priority", int.class, () -> Configuration.caveSettings.caves.vanillaCave.cavePriority, v -> Configuration.caveSettings.caves.vanillaCave.cavePriority = (Integer)v).comment("Determines how frequently vanilla caves spawn. 0 = will not spawn at all.\nDefault: 0").langKey("bettercaves.general.underground generation.caves.vanilla caves.cavepriority").range(0, 10).requiresWorldRestart()).comment("Settings controlling vanilla Minecraft cave generation.").langKey("bettercaves.general.underground generation.caves.vanillacave"),
               ConfigEntry.value("Cave Spawn Chance", float.class, () -> Configuration.caveSettings.caves.caveSpawnChance, v -> Configuration.caveSettings.caves.caveSpawnChance = (Float)v).comment("Percent chance of caves spawning in a given region.\nDefault: caves spawn in 100% of regions.").langKey("bettercaves.general.underground generation.caves.cavespawnchance").range(0.0, 100.0).requiresWorldRestart(),
               ConfigEntry.enumValue("Cave Region Size", com.yungnickyoung.minecraft.bettercaves.enums.RegionSize.values(), () -> Configuration.caveSettings.caves.caveRegionSize, v -> Configuration.caveSettings.caves.caveRegionSize = v).comment("Determines how large cave regions are.\n    Controls how long a cave system of a certain cave type extends before intersecting with a cave system of another type.\n    Larger = more cave interconnectivity for a given area, but less variation.\nDefault: Small (recommended).").langKey("bettercaves.general.underground generation.caves.caveregionsize").requiresWorldRestart(),
               ConfigEntry.value("Cave Region Size Custom Value", float.class, () -> Configuration.caveSettings.caves.customRegionSize, v -> Configuration.caveSettings.caves.customRegionSize = (Float)v).comment("Custom value for cave region size. Smaller value = larger regions. This value is very sensitive to change.\n    ONLY WORKS IF Cave Region Size IS Custom.\n    Provided values:\n        Small: 0.008\n        Medium: 0.005\n        Large: 0.0032\n        ExtraLarge: 0.001\nDefault: 0.008").langKey("bettercaves.general.underground generation.caves.customregionsize").range(0.0, 0.05).requiresWorldRestart()).comment("Settings used in the generation of caves.").langKey("bettercaves.general.underground generation.caves"),
            ConfigEntry.category("Caverns",
               ConfigEntry.category("Liquid Caverns",
                  ConfigEntry.value("Liquid Cavern Minimum Altitude", int.class, () -> Configuration.caveSettings.caverns.liquidCavern.cavernBottom, v -> Configuration.caveSettings.caverns.liquidCavern.cavernBottom = (Integer)v).comment("The minimum y-coordinate at which Liquid Caverns can generate.\nDefault: 1").langKey("bettercaves.general.underground generation.caverns.liquid caverns.cavernbottom").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Liquid Cavern Maximum Altitude", int.class, () -> Configuration.caveSettings.caverns.liquidCavern.cavernTop, v -> Configuration.caveSettings.caverns.liquidCavern.cavernTop = (Integer)v).comment("The maximum y-coordinate at which Liquid Caverns can generate.\n    Caverns will attempt to close off anyway if this value is greater than the surface's altitude.\nDefault: 35").langKey("bettercaves.general.underground generation.caverns.liquid caverns.caverntop").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Compression - Vertical", float.class, () -> Configuration.caveSettings.caverns.liquidCavern.yCompression, v -> Configuration.caveSettings.caverns.liquidCavern.yCompression = (Float)v).comment("Stretches caverns vertically. Lower value = more open caverns with larger features.\nDefault: 1.3").langKey("bettercaves.general.underground generation.caverns.liquid caverns.ycompression").range(0.0, 100.0).requiresWorldRestart(),
                  ConfigEntry.value("Compression - Horizontal", float.class, () -> Configuration.caveSettings.caverns.liquidCavern.xzCompression, v -> Configuration.caveSettings.caverns.liquidCavern.xzCompression = (Float)v).comment("Stretches caverns horizontally. Lower value = more open caverns with larger features.\nDefault: 0.7").langKey("bettercaves.general.underground generation.caverns.liquid caverns.xzcompression").range(0.0, 100.0).requiresWorldRestart(),
                  ConfigEntry.value("Liquid Cavern Priority", int.class, () -> Configuration.caveSettings.caverns.liquidCavern.cavernPriority, v -> Configuration.caveSettings.caverns.liquidCavern.cavernPriority = (Integer)v).comment("Determines how frequently Liquid Caverns spawn. 0 = will not spawn at all.\nDefault: 10").langKey("bettercaves.general.underground generation.caverns.liquid caverns.cavernpriority").range(0, 10).requiresWorldRestart()).comment("Settings used in the generation of Liquid Caverns found at low altitudes.\n    These are caverns where the floor is predominantly water or lava.").langKey("bettercaves.general.underground generation.caverns.liquidcavern"),
               ConfigEntry.category("Floored Caverns",
                  ConfigEntry.value("Floored Cavern Minimum Altitude", int.class, () -> Configuration.caveSettings.caverns.flooredCavern.cavernBottom, v -> Configuration.caveSettings.caverns.flooredCavern.cavernBottom = (Integer)v).comment("The minimum y-coordinate at which Floored Caverns can generate.\nDefault: 1").langKey("bettercaves.general.underground generation.caverns.floored caverns.cavernbottom").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Floored Cavern Maximum Altitude", int.class, () -> Configuration.caveSettings.caverns.flooredCavern.cavernTop, v -> Configuration.caveSettings.caverns.flooredCavern.cavernTop = (Integer)v).comment("The maximum y-coordinate at which Floored Caverns can generate.\n    Caverns will attempt to close off anyway if this value is greater than the surface's altitude.\nDefault: 35").langKey("bettercaves.general.underground generation.caverns.floored caverns.caverntop").range(0, 255).requiresWorldRestart(),
                  ConfigEntry.value("Compression - Vertical", float.class, () -> Configuration.caveSettings.caverns.flooredCavern.yCompression, v -> Configuration.caveSettings.caverns.flooredCavern.yCompression = (Float)v).comment("Stretches caverns vertically. Lower value = more open caverns with larger features.\nDefault: 1.3").langKey("bettercaves.general.underground generation.caverns.floored caverns.ycompression").range(0.0, 100.0).requiresWorldRestart(),
                  ConfigEntry.value("Compression - Horizontal", float.class, () -> Configuration.caveSettings.caverns.flooredCavern.xzCompression, v -> Configuration.caveSettings.caverns.flooredCavern.xzCompression = (Float)v).comment("Stretches caverns horizontally. Lower value = more open caverns with larger features.\nDefault: 0.7").langKey("bettercaves.general.underground generation.caverns.floored caverns.xzcompression").range(0.0, 100.0).requiresWorldRestart(),
                  ConfigEntry.value("Floored Cavern Priority", int.class, () -> Configuration.caveSettings.caverns.flooredCavern.cavernPriority, v -> Configuration.caveSettings.caverns.flooredCavern.cavernPriority = (Integer)v).comment("Determines how frequently Floored Caverns spawn. 0 = will not spawn at all.\nDefault: 10").langKey("bettercaves.general.underground generation.caverns.floored caverns.cavernpriority").range(0, 10).requiresWorldRestart()).comment("Parameters used in the generation of Floored Caverns.\n    These have much more ground to walk on than Liquid Caverns.").langKey("bettercaves.general.underground generation.caverns.flooredcavern"),
               ConfigEntry.value("Cavern Spawn Chance", float.class, () -> Configuration.caveSettings.caverns.cavernSpawnChance, v -> Configuration.caveSettings.caverns.cavernSpawnChance = (Float)v).comment("Percent chance of caverns spawning in a given region.\nDefault: caverns spawn in 25% of regions.").langKey("bettercaves.general.underground generation.caverns.cavernspawnchance").range(0.0, 100.0).requiresWorldRestart(),
               ConfigEntry.enumValue("Cavern Region Size", com.yungnickyoung.minecraft.bettercaves.enums.RegionSize.values(), () -> Configuration.caveSettings.caverns.cavernRegionSize, v -> Configuration.caveSettings.caverns.cavernRegionSize = v).comment("Determines how large cavern regions are. This controls the average size of caverns.\nDefault: Small").langKey("bettercaves.general.underground generation.caverns.cavernregionsize").requiresWorldRestart(),
               ConfigEntry.value("Cavern Region Size Custom Value", float.class, () -> Configuration.caveSettings.caverns.customRegionSize, v -> Configuration.caveSettings.caverns.customRegionSize = (Float)v).comment("Custom value for cavern region size. Only works if Cavern Region Size is set to Custom.     Smaller value = larger regions. This value is very sensitive to change.\n    Provided values:\n        Small: 0.01\n        Medium: 0.007\n        Large: 0.005\n        ExtraLarge: 0.001\nDefault: 0.01").langKey("bettercaves.general.underground generation.caverns.customregionsize").range(0.0, 0.05).requiresWorldRestart()).comment("Settings used in the generation of caverns. Caverns are spacious caves at low altitudes.").langKey("bettercaves.general.underground generation.caverns"),
            ConfigEntry.category("Water Regions",
               ConfigEntry.value("Water Region Spawn Chance", float.class, () -> Configuration.caveSettings.waterRegions.waterRegionSpawnChance, v -> Configuration.caveSettings.waterRegions.waterRegionSpawnChance = (Float)v).comment("Percent chance of a region having water instead of lava at low altitudes.\nDefault: 40%").langKey("bettercaves.general.underground generation.water regions.waterregionspawnchance").range(0.0, 100.0).requiresWorldRestart(),
               ConfigEntry.enumValue("Water Region Size", com.yungnickyoung.minecraft.bettercaves.enums.RegionSize.values(), () -> Configuration.caveSettings.waterRegions.waterRegionSize, v -> Configuration.caveSettings.waterRegions.waterRegionSize = v).comment("Determines how large water regions are.\nDefault: Medium (recommended).").langKey("bettercaves.general.underground generation.water regions.waterregionsize").requiresWorldRestart(),
               ConfigEntry.value("Water Region Size Custom Value", float.class, () -> Configuration.caveSettings.waterRegions.waterRegionCustomSize, v -> Configuration.caveSettings.waterRegions.waterRegionCustomSize = (Float)v).comment("Custom value for water region size. Smaller value = larger regions. This value is very sensitive to change.\n    ONLY WORKS IF Water Region Size IS Custom.\n    Provided values:\n        Small: 0.008\n        Medium: 0.004\n        Large: 0.0028\n        ExtraLarge: 0.001\nDefault: 0.004").langKey("bettercaves.general.underground generation.water regions.waterregioncustomsize").range(0.0, 0.05).requiresWorldRestart()).comment("Settings used in the generation of water regions.").langKey("bettercaves.general.underground generation.waterregions"),
            ConfigEntry.category("Ravines",
               ConfigEntry.value("Enable Ravines", boolean.class, () -> Configuration.caveSettings.ravines.enableVanillaRavines, v -> Configuration.caveSettings.ravines.enableVanillaRavines = (Boolean)v).comment("Set to true to enable ravine generation.\nDefault: true").langKey("bettercaves.general.underground generation.ravines.enablevanillaravines"),
               ConfigEntry.value("Enable Flooded Ravines", boolean.class, () -> Configuration.caveSettings.ravines.enableFloodedRavines, v -> Configuration.caveSettings.ravines.enableFloodedRavines = (Boolean)v).comment("Set to true to enable flooded ravines in ocean biomes.\nDefault: true").langKey("bettercaves.general.underground generation.ravines.enablefloodedravines")).comment("Settings used for ravine generation.").langKey("bettercaves.general.underground generation.ravines"),
            ConfigEntry.category("Miscellaneous",
               ConfigEntry.value("Liquid Altitude", int.class, () -> Configuration.caveSettings.miscellaneous.liquidAltitude, v -> Configuration.caveSettings.miscellaneous.liquidAltitude = (Integer)v).comment("Lava (or water in water regions) spawns at and below this y-coordinate.\nDefault: 10").langKey("bettercaves.general.underground generation.miscellaneous.liquidaltitude").range(0, 255).requiresWorldRestart(),
               ConfigEntry.value("Lava Block", String.class, () -> Configuration.caveSettings.miscellaneous.lavaBlock, v -> Configuration.caveSettings.miscellaneous.lavaBlock = (String)v).comment("The block used for lava generation at and below the Liquid Altitude.\n    Defaults to regular lava if an invalid block is given.\nDefault: minecraft:lava").langKey("bettercaves.general.underground generation.miscellaneous.lavablock").requiresWorldRestart(),
               ConfigEntry.value("Water Block", String.class, () -> Configuration.caveSettings.miscellaneous.waterBlock, v -> Configuration.caveSettings.miscellaneous.waterBlock = (String)v).comment("The block used for water generation in water caves/caverns at and below the Liquid Altitude.\n    Defaults to regular water if an invalid block is given.\nDefault: minecraft:water").langKey("bettercaves.general.underground generation.miscellaneous.waterblock").requiresWorldRestart(),
               ConfigEntry.value("Prevent Cascading Gravel", boolean.class, () -> Configuration.caveSettings.miscellaneous.replaceFloatingGravel, v -> Configuration.caveSettings.miscellaneous.replaceFloatingGravel = (Boolean)v).comment("Replace naturally generated floating gravel on the ocean floor with andesite.\n    Can prevent lag due to cascading gravel falling into caverns under the ocean.\nDefault: true").langKey("bettercaves.general.underground generation.miscellaneous.replacefloatinggravel").requiresWorldRestart(),
               ConfigEntry.value("Override Surface Detection", boolean.class, () -> Configuration.caveSettings.miscellaneous.overrideSurfaceDetection, v -> Configuration.caveSettings.miscellaneous.overrideSurfaceDetection = (Boolean)v).comment("Ignores surface detection for closing off caves and caverns, forcing them to spawn\n    up until their max height. Useful for Nether-like dimensions with no real \"surface\".\nDefault: false").langKey("bettercaves.general.underground generation.miscellaneous.overridesurfacedetection").requiresWorldRestart(),
               ConfigEntry.value("Enable Flooded Underground", boolean.class, () -> Configuration.caveSettings.miscellaneous.enableFloodedUnderground, v -> Configuration.caveSettings.miscellaneous.enableFloodedUnderground = (Boolean)v).comment("Set to true to enable flooded underground in ocean biomes.\nDefault: true").langKey("bettercaves.general.underground generation.miscellaneous.enablefloodedunderground")).comment("Miscellaneous settings used in cave and cavern generation.").langKey("bettercaves.general.underground generation.miscellaneous")).comment("Configure settings related to caves, caverns, ravines and more.").langKey("bettercaves.general.cavesettings"),
         ConfigEntry.category("Bedrock Generation",
            ConfigEntry.value("Flatten Bedrock", boolean.class, () -> Configuration.bedrockSettings.flattenBedrock, v -> Configuration.bedrockSettings.flattenBedrock = (Boolean)v).comment("Replaces the usual bedrock generation pattern with flat layers.\n    Activates in all whitelisted dimension, where applicable. The End is unaffected.").langKey("bettercaves.general.bedrock generation.flattenbedrock").requiresWorldRestart(),
            ConfigEntry.value("Bedrock Layer Width", int.class, () -> Configuration.bedrockSettings.bedrockWidth, v -> Configuration.bedrockSettings.bedrockWidth = (Integer)v).comment("The width of the bedrock layer. Only works if Flatten Bedrock is true.").langKey("bettercaves.general.bedrock generation.bedrockwidth").range(0, 256).requiresWorldRestart()).comment("Configure how bedrock generates in the overworld and nether.").langKey("bettercaves.general.bedrocksettings"),
         ConfigEntry.category("Debug settings",
            ConfigEntry.value("Enable DEBUG Visualizer", boolean.class, () -> Configuration.debugsettings.debugVisualizer, v -> Configuration.debugsettings.debugVisualizer = (Boolean)v).comment("The visualizer creates worlds where there are no blocks except those indicating where caves\n    and caverns would be carved out in a regular world. This is useful for visualizing the kinds of\n    caves and caverns your current config options will create.\n    Type 1 Cave: Wooden Planks\n    Type 2 Cave: Cobblestone\n    Lava Cavern: Redstone Block\n    Floored Cavern: Gold Block\n    Surface Cave: Emerald Block\n    Vanilla Cave: Bricks\nDefault: false").langKey("bettercaves.general.debug settings.debugvisualizer")).comment("Don't mess with these settings for normal gameplay.").langKey("bettercaves.general.debugsettings"),
         ConfigEntry.value("Whitelisted Dimension IDs", int[].class, () -> Configuration.whitelistedDimensionIDs, v -> Configuration.whitelistedDimensionIDs = (int[])v).comment("List of ID's of dimensions that will have Better Caves. Ignored if Global Whitelisting is enabled.").langKey("bettercaves.general.whitelisteddimensionids").requiresWorldRestart(),
         ConfigEntry.value("Enable Global Whitelist", boolean.class, () -> Configuration.enableGlobalWhitelist, v -> Configuration.enableGlobalWhitelist = (Boolean)v).comment("Automatically enables Better Caves in every possible dimension, except for the End.\n    If this is enabled, the Whitelisted Dimension IDs option is ignored.\nDefault: false").langKey("bettercaves.general.enableglobalwhitelist").requiresWorldRestart());
   }
}
